import { retentionMs } from './policy.mjs';

// Identity is the pair (tenantId, key). Punctuation is allowed in both parts,
// so the composite identity is encoded as a length-prefixed tuple rather than
// joined with an unescaped delimiter.
function identityOf(tenantId, key) {
  const t = String(tenantId);
  const k = String(key);
  return `${t.length}:${t}|${k.length}:${k}`;
}

export function createStore() {
  const entries = new Map();

  function readEntry(tenantId, key) {
    const id = identityOf(tenantId, key);
    const entry = entries.get(id);
    if (!entry) return null;
    return entry;
  }

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const entry = readEntry(tenantId, key);
      if (!entry) return { kind: 'miss' };

      // Expire exactly at saved time + retentionMs (inclusive), even when the
      // presented fingerprint differs from the stored one.
      if (now >= entry.savedAt + retentionMs) {
        entries.delete(identityOf(tenantId, key));
        return { kind: 'miss' };
      }

      if (entry.fingerprint !== fingerprint) {
        return { kind: 'conflict' };
      }

      return { kind: 'hit', response: entry.response };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      entries.set(identityOf(tenantId, key), {
        fingerprint,
        response,
        savedAt: now,
      });
    },
  };
}

