export const IDEMPOTENCY_HEADER = 'Idempotency-Key';

const CONFLICT_RESPONSE = Object.freeze({
  status: 409,
  body: { error: 'idempotency_conflict' },
});

function isCacheable(response) {
  return (
    response !== null &&
    typeof response === 'object' &&
    typeof response.status === 'number' &&
    response.status >= 200 &&
    response.status < 300
  );
}

/**
 * Import one invoice with idempotency guarantees.
 *
 * - Sends exactly the header `Idempotency-Key`.
 * - Identity is the pair (tenantId, key); the key alone is never the identity.
 * - A stored entry for the same identity with a matching fingerprint replays
 *   the original successful response without sending anything.
 * - An unexpired entry with a different fingerprint yields the documented
 *   conflict response.
 * - Only 2xx responses are cached.
 * - Transport exceptions from `send` propagate and leave no cache entry.
 * - Retries only per `retryDelay` (429/502/503/504), waiting via `deps.wait`,
 *   using injected `deps.now()` for timestamps and never real timers.
 */
export async function importInvoice(request, deps) {
  const { tenantId, key, fingerprint, payload } = request;
  const { store, now, send, wait } = deps;

  const cached = store.lookup({ tenantId, key, fingerprint, now: now() });
  if (cached.kind === 'hit') return cached.response;
  if (cached.kind === 'conflict') return CONFLICT_RESPONSE;

  const headers = { [IDEMPOTENCY_HEADER]: key };
  const body = payload;

  let attempt = 1;
  for (;;) {
    const response = await send({ headers, body });

    const delay = retryDelay(response.status, attempt);
    if (delay === null) {
      if (isCacheable(response)) {
        store.save({
          tenantId,
          key,
          fingerprint,
          response,
          now: now(),
        });
      }
      return response;
    }

    await wait(delay);
    attempt += 1;
  }
}

/**
 * Import several invoices sequentially with the same dependency object.
 *
 * - Requests are processed one at a time, in input order, so each item sees
 *   the cache effects of the items before it.
 * - Responses are returned in input order.
 * - A terminal HTTP failure response (for example 422 or 409) never stops the
 *   batch; that response is simply recorded and processing continues.
 * - A thrown transport exception propagates out of `importBatch` immediately,
 *   so remaining requests are not attempted.
 */
export async function importBatch(requests, deps) {
  const responses = [];
  for (const request of requests) {
    responses.push(await importInvoice(request, deps));
  }
  return responses;
}

