export async function importBatch(requests, deps) {
  const responses = [];
  for (const request of requests) {
    // Sequential: await each import before starting the next. HTTP failure
    // responses do not stop the batch; thrown transport exceptions propagate
    // and abort the remaining items.
    responses.push(await importInvoice(request, deps));
  }
  return responses;
}
